const busy=ref(false),error=ref(''),notice=ref(''),ws=ref<any>(null),page=ref('home'),action=ref(''),activeDataset=ref(''),detail=ref<any>(null),result=ref<any>(null),loadedPlan=ref<Row|null>(null),slots=ref<any[]>([]),selectedSlot=ref<any>(null),pendingKey=ref(''),lastPayload=ref('')
// Keep the custom navigation below the real WeChat status bar and capsule.
