const query=ref(''),resourceImpact=ref<Row|null>(null),billingReview=ref<Row|null>(null),recordFocus=ref<Row|null>(null),editorSubject=ref('')
const credentials=reactive({login_name:'',password:''});const form=reactive<Record<string,any>>({});const resources=computed(()=>ws.value?.resources||{});const personal=computed(()=>['patient','representative'].includes(ws.value?.scope.role_code));const menu=computed(()=>ws.value?.menu||[])
const personalProfile=computed(()=>page.value==='UC01'&&personal.value)
