const currentMenu=computed(()=>menu.value.find((m:any)=>m.code===page.value));const availableActions=computed(()=>{
 let list=forms[page.value]||[];const role=ws.value?.scope.role_code
 if(page.value==='UC04')list=list.filter(a=>role==='patient'?['arrive','leave'].includes(a.key):role==='dentist'?['start','correct'].includes(a.key):['arrive','no_show','leave'].includes(a.key))
 if(page.value==='UC01'&&['patient','representative'].includes(role))list=list.filter(a=>['save','contact','allergy'].includes(a.key))
 if(page.value==='UC06')list=list.filter(a=>role==='manager'?['correct','approve-price'].includes(a.key):role==='dentist'?['issue','prepare-correction'].includes(a.key):a.key==='issue')
 if(page.value==='UC16'&&role==='business')list=list.filter(a=>a.key!=='grant')
 if(page.value==='UC01'&&role==='dentist')list=list.filter(a=>a.key!=='save')
 if(page.value==='UC03')list=list.filter(a=>personal.value?!['contact','assign'].includes(a.key):a.key!=='assign'||role==='manager')
 if(page.value==='UC09'&&role==='business')list=list.filter(a=>!['replace','stop'].includes(a.key))
