 if(page.value==='UC11')list=list.filter(a=>role==='manager'?a.key.startsWith('review'):!a.key.startsWith('review'))
 if(page.value==='UC12'&&role==='manager')list=list.filter(a=>a.key!=='confirm')
 if(page.value==='UC16'&&role==='reception')list=list.filter(a=>['create','grant','disable','enable','password'].includes(a.key))
 if(page.value==='UC09')list.sort((a,b)=>['publish','replace','stop','travel-rule'].indexOf(a.key)-['publish','replace','stop','travel-rule'].indexOf(b.key))
 if(page.value==='UC13')list.sort((a,b)=>['confirm','draft','phase'].indexOf(a.key)-['confirm','draft','phase'].indexOf(b.key))
 if(page.value==='UC16')list.sort((a,b)=>['create','grant','revoke','password','disable','enable'].indexOf(a.key)-['create','grant','revoke','password','disable','enable'].indexOf(b.key))
 return list
});const activeForm=computed(()=>{const spec=availableActions.value.find(a=>a.key===action.value);return spec?{...spec,fields:spec.fields.map(f=>page.value==='UC01'&&f.key==='verification_result'&&ws.value?.scope.role_code!=='dentist'?{...f,type:'enum:reported=本人或代办人申报，尚待牙医核实'}:f).map(f=>page.value==='UC01'&&action.value==='save'&&f.key==='change_reason'&&form.id?{...f,required:true}:f).filter(f=>!(personalProfile.value&&f.key==='id')&&!(personal.value&&['initiator_kind','identity_confirmed','identity_check_basis'].includes(f.key))&&!(page.value==='UC15'&&form.change_mode!=='immediate'&&['unavailable_reason','impact_acknowledged'].includes(f.key)))}:undefined});const list=computed(()=>resources.value[activeDataset.value]||[])
const formResources=computed(()=>{const encounter=(resources.value.encounters||[]).find((e:Row)=>e.id===form.encounter_id);const patientId=page.value==='UC01'?form.id:encounter?.patient_id;return {...resources.value,patients:page.value==='UC16'?(resources.value.account_patients||resources.value.patients||[]):resources.value.patients,contacts:(resources.value.contacts||[]).filter((c:Row)=>!patientId||c.patient_id===patientId),authorities:(resources.value.authorities||[]).filter((a:Row)=>(patientId?a.patient_id===patientId:!['UC05','UC13'].includes(page.value))&&(!['UC05','UC13'].includes(page.value)||['consent','all'].includes(a.permission_scope))),...(page.value==='UC01'&&action.value==='authority'?{accounts:(resources.value.accounts||[]).filter((a:Row)=>a.account_kind==='representative'&&a.is_enabled)}:{})}})
const bookingMode=computed(()=>page.value==='UC02'||(page.value==='UC03'&&action.value==='reschedule'))
const bookingFields:Field[]=[{key:'presenting_request',label:'症状或就诊诉求（项目与诉求至少一项）',type:'textarea',required:false},{key:'special_needs',label:'特殊需要或注意事项（选填）',type:'textarea',required:false},{key:'patient_id',label:'就诊人',type:'select:patients',required:true},{key:'clinic_id',label:'门店',type:'select:clinics',required:true},{key:'standard_ids',label:'拟治疗项目',type:'multi:standards',required:false},{key:'date',label:'就诊日期',type:'date',required:true},{key:'phase_id',label:'接续已获准阶段（选填）',type:'select:phases',required:false}]
const booking=reactive<any>({patient_id:'',clinic_id:'',standard_ids:[],date:'',phase_id:''})
const clinicalLines=ref<any[]>([]),allocations=ref<any[]>([]),phases=ref<any[]>([]),dependencies=ref<any[]>([]),phaseResults=ref<any[]>([])
const showingLists=computed(()=>datasets[page.value]||[])
const isRemoteList=computed(()=>['patients','appointments','invoices'].includes(activeDataset.value))
const rowActions=computed(()=>recordFocus.value&&!personal.value ? actionsForRecord(page.value,activeDataset.value,recordFocus.value,
  ws.value?.scope.role_code,ws.value?.server_time).filter(task=>availableActions.value.some(form=>form.key===task.action)) : [])
const clinicalField:Field[]=[{key:'performed_at',label:'实际实施时点（更正沿用原时点，补录请明确）',type:'datetime',required:false},{key:'standard_id',label:'实际项目',type:'select:standards',required:true},{key:'phase_item_id',label:'对应方案项目（选填）',type:'select:phase_items',required:false},{key:'site_description',label:'部位',type:'text',required:false},{key:'actual_quantity',label:'实际实施数量',type:'number',required:true},{key:'charged_unit_price',label:'单位价格（元）',type:'number',required:false},{key:'implementation_result',label:'实施结论',type:'enum:performed=已实施,interrupted=部分实施后中止,deferred=暂缓未实施',required:true}]
const allocationFields:Field[]=[{key:'quarter_id',label:'费用季度',type:'select:quarters',required:true},{key:'dentist_id',label:'归属牙医',type:'select:dentists',required:true},{key:'clinic_id',label:'归属门店',type:'select:clinics',required:true},{key:'allocated_amount',label:'分摊金额（元）',type:'number',required:true},{key:'allocation_basis',label:'归属依据',type:'text',required:true}]
const phaseFields:Field[]=[{key:'phase_no',label:'阶段序号',type:'number',required:true},{key:'phase_title',label:'阶段名称',type:'text',required:true},{key:'clinical_condition',label:'临床先决条件',type:'textarea',required:true},{key:'responsible_clinic_id',label:'承接门店',type:'select:clinics',required:true},{key:'estimated_fee',label:'预计费用（元）',type:'number',required:false},{key:'earliest_at',label:'最早可约时点',type:'datetime',required:false},{key:'latest_at',label:'最晚可约时点',type:'datetime',required:false},{key:'clinical_released',label:'牙医已核实并放行可约条件',type:'boolean',required:false}]
function toast(s:string){notice.value=s;setTimeout(()=>notice.value='',6000)}
async function refresh(){ws.value=await loadWorkspace(true);session.scope=ws.value?.scope;if(personalProfile.value&&profilePatient.value.id)detail.value=await request('/api/patients/'+profilePatient.value.id)}
async function enter(){busy.value=true;error.value='';try{await login(credentials.login_name,credentials.password);credentials.password='';await refresh()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function logout(){session.token='';uni.removeStorageSync('adc-token');ws.value=null;page.value='home';uni.reLaunch({url:'/pages/index/index'})}
async function changeScope(e:any){busy.value=true;try{await switchScope(ws.value.scopes[Number(e.detail.value)].id);page.value='home';await refresh()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function choose(code:string){recordFocus.value=null;if(code==='home'){uni.reLaunch({url:'/pages/index/index'});return}page.value=code;error.value='';detail.value=null;result.value=null;slots.value=[];selectedSlot.value=null;activeDataset.value=(datasets[code]||[])[0]||'';action.value=availableActions.value[0]?.key||'';resetForm()}
let loadedPlanDigest=''
function planDefinition(){return JSON.stringify({phases:phases.value.map(p=>({phase_no:Number(p.phase_no),phase_title:p.phase_title,clinical_condition:p.clinical_condition,responsible_clinic_id:Number(p.responsible_clinic_id),earliest_at:p.earliest_at?new Date(p.earliest_at).toISOString():null,latest_at:p.latest_at?new Date(p.latest_at).toISOString():null,estimated_fee:p.estimated_fee==null?null:Number(p.estimated_fee),items:(p.items||[]).map((i:Row)=>({standard_id:Number(i.standard_id),site_description:i.site_description||'',planned_quantity:Number(i.planned_quantity)}))})).sort((a,b)=>a.phase_no-b.phase_no),dependencies:dependencies.value.map(d=>[Number(d.predecessor),Number(d.successor)]).sort((a,b)=>a[0]-b[0]||a[1]-b[1])})}
function resetForm(){editorSubject.value='';loadedPlan.value=null;loadedPlanDigest='';resourceImpact.value=null;billingReview.value=null;Object.keys(form).forEach(k=>delete form[k]);pendingKey.value='';lastPayload.value='';result.value=null;clinicalLines.value=[];allocations.value=[];phases.value=[];dependencies.value=[];phaseResults.value=[];for(const f of activeForm.value?.fields||[]){if(f.type?.startsWith('enum:')&&f.required)form[f.key]=f.type.slice(5).split(',')[0].split('=')[0];else if(f.type==='boolean')form[f.key]=f.key==='is_open';}if(page.value==='UC01'&&personal.value){const p=resources.value.patients?.[0];if(p){if(action.value==='save'){Object.assign(form,p);fillEmergency(p.id)}else{form.id=p.id;if(action.value==='allergy')form.report_source=ws.value?.scope.role_code==='representative'?'授权代办人申报':'患者本人申报'}}}if(page.value==='UC15')form.session_no=1;if(page.value==='UC10'){form.quantity_scale=0;form.duration_minutes=30}if(page.value==='UC11')form.source_line_no=1;booking.patient_id=ws.value?.account.patient_id||resources.value.patients?.[0]?.id||'';booking.clinic_id=resources.value.clinics?.[0]?.id||'';booking.date=new Date(Date.now()+86400000).toISOString().slice(0,10);booking.standard_ids=[];booking.phase_id='';booking.presenting_request='';booking.special_needs='';if(page.value==='UC05')addClinical();if(page.value==='UC11')addAllocation();if(page.value==='UC13')addPhase()}
function fillEmergency(id:any){const contact=[...(resources.value.contacts||[])].reverse().find((c:Row)=>c.patient_id===id&&c.contact_purpose==='emergency');if(contact)Object.assign(form,{emergency_name:contact.full_name,emergency_phone:contact.phone,emergency_relationship:contact.relationship})}
function changeAction(key:string){action.value=key;error.value='';detail.value=null;resetForm()}
function addClinical(){clinicalLines.value.push({standard_id:'',actual_quantity:1,implementation_result:'performed'})}
function addAllocation(){allocations.value.push({quarter_id:resources.value.quarters?.[0]?.id,dentist_id:resources.value.dentists?.[0]?.id,clinic_id:resources.value.clinics?.[0]?.id,allocated_amount:'',allocation_basis:''})}
function addPhase(){phases.value.push({phase_no:phases.value.length+1,phase_title:'',clinical_condition:'',responsible_clinic_id:resources.value.clinics?.[0]?.id,clinical_released:false,items:[]})}
function openInvoiceCopy(){if(detail.value?.id)uni.navigateTo({url:'/pages/invoice/index?id='+detail.value.id})}
function labelRow(r:any){return optionLabel(r)}
async function inspect(row:any){error.value='';detail.value=row
 if(activeDataset.value==='invoices'){try{detail.value=await request('/api/invoices/'+row.id)}catch(e:any){error.value=e.message}}
 else if(activeDataset.value==='encounters'&&page.value==='UC05'){
  try{const d=await request('/api/encounters/'+row.id);detail.value=d;form.encounter_id=row.id;phaseResults.value=(d.phases||[]).map((p:any)=>({phase_id:p.id,outcome:''}));if(d.notes?.[0]){const n=d.notes[0];for(const k of ['chief_complaint','present_illness','medical_history','examination_summary','tests_summary','diagnosis_summary','management_summary','aftercare','allergy_review'])form[k]=n[k];form.previous_note_id=n.id;clinicalLines.value=d.treatments.filter((t:any,i:number,rows:any[])=>rows.findIndex(v=>v.treatment_id===t.treatment_id)===i).map((t:any)=>({treatment_id:t.treatment_id,performed_at:t.performed_at,standard_id:t.standard_id,site_description:t.site_description,actual_quantity:Number(t.actual_quantity),charged_unit_price:t.charged_unit_price,implementation_result:t.implementation_result,phase_item_id:t.phase_item_id}))}}catch(e:any){error.value=e.message}
 }else if(activeDataset.value==='phases'&&page.value==='UC13'&&action.value!=='phase'){try{const d=await request('/api/plans/'+row.plan_id);form.plan_id=d.id;form.row_version=d.row_version;form.encounter_id=d.origin_encounter_id;phases.value=d.phases;dependencies.value=d.dependencies;loadedPlan.value=d;loadedPlanDigest=planDefinition();detail.value=d}catch(e:any){error.value=e.message}}
}
watch(()=>form.encounter_id,async (id,_,onCleanup)=>{
 billingReview.value=null
 if(page.value!=='UC06'||!id)return
 let current=true
 onCleanup(()=>current=false)
 try{const result=await request('/api/billing/'+id);if(current)billingReview.value=result}
 catch(e:any){if(current)error.value=e.message}
})
watch(()=>[page.value,action.value,form.id],async()=>{resourceImpact.value=null;if(page.value!=='UC15'||!form.id)return;try{resourceImpact.value=await request('/api/resources/impact?kind='+action.value+'&id='+form.id)}catch(e:any){error.value=e.message}})
watch(()=>form.id,id=>{if(!id)return;if(page.value==='UC09'){const d=(resources.value.duties||[]).find((x:any)=>x.id===id);if(d)form.row_version=d.row_version}const r=(resources.value.appointments||[]).find((x:any)=>x.id===id);if(page.value==='UC03'&&action.value==='assign'){const task=(resources.value.followups||[]).find((x:any)=>x.id===id);if(task)form.row_version=task.row_version}if(['UC03'].includes(page.value)&&r&&action.value!=='assign'){form.row_version=r.row_version;booking.patient_id=r.patient_id;booking.clinic_id=r.clinic_id}})
watch(()=>[booking.clinic_id,booking.patient_id,booking.date,booking.standard_ids,booking.phase_id],()=>{slots.value=[];selectedSlot.value=null},{deep:true})
async function findSlots(){busy.value=true;error.value='';try{if(!booking.patient_id||!booking.clinic_id||!booking.date)throw new Error('请先选择就诊人、门店与日期');const chosen=(resources.value.standards||[]).filter((s:any)=>booking.standard_ids.includes(s.id));if(!chosen.length&&!booking.presenting_request?.trim())throw new Error('请选择项目或填写就诊诉求');const minutes=chosen.reduce((sum:number,s:any)=>sum+s.duration_minutes,0)||30;const q=Object.entries({...booking,standard_ids:booking.standard_ids.join(','),minutes,presenting_request:booking.presenting_request||'按所选项目安排'}).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>encodeURIComponent(k)+'='+encodeURIComponent(String(v))).join('&');slots.value=(await request('/api/slots?'+q)).slots;if(!slots.value.length)toast('所选日期暂无符合条件的完整时段，请更换日期或门店')}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function submit(){error.value='';busy.value=true;try{
 if(['UC14','UC17'].includes(page.value)){if(page.value==='UC17')result.value=await request('/api/audit');else await refresh();return}
 let payload:any={action:action.value};if(personalProfile.value)payload.id=profilePatient.value.id;for(const field of activeForm.value?.fields||[]){const v=form[field.key];if(field.required&&field.type!=='record'&&(v===null||v===undefined||v===''))throw new Error('请填写'+field.label);if(v!==undefined&&v!=='')payload[field.key]=v}
 for(const k of ['row_version','previous_note_id'])if(form[k]!=null)payload[k]=form[k]
 if(bookingMode.value){if(!selectedSlot.value)throw new Error('请选择一个完整可约时段');const target={...selectedSlot.value,patient_id:booking.patient_id,standard_ids:booking.standard_ids,presenting_request:booking.presenting_request||'按所选项目安排',special_needs:booking.special_needs||'',...(booking.phase_id?{phase_id:booking.phase_id}:{})};if(page.value==='UC03')payload.replacement=target;else payload={...payload,...target}}
 if(page.value==='UC05'){payload.treatments=clinicalLines.value.map(line=>{const s=(resources.value.standards||[]).find((s:any)=>s.id===line.standard_id);if(!s)throw new Error('请选择每一项实际治疗');return {...line,charged_unit_price:line.charged_unit_price??s.unit_price}});payload.phase_results=phaseResults.value.filter(r=>r.phase_id)}
 if(page.value==='UC11'&&action.value==='source')payload.allocations=allocations.value
 if(page.value==='UC13'&&action.value!=='phase'){payload.phases=phases.value;payload.dependencies=dependencies.value.map(e=>[Number(e.predecessor),Number(e.successor)]);if(form.plan_id)payload.id=form.plan_id;if(action.value==='confirm'&&loadedPlan.value?.revision?.confirmation_state==='draft'&&loadedPlanDigest===planDefinition()){payload.confirm_existing_revision=true;payload.version=loadedPlan.value.revision.revision_no;payload.released_phase_ids=phases.value.filter(p=>p.clinical_released).map(p=>p.phase_id||p.id)}}
 if(page.value==='UC15'&&form.change_mode==='immediate'){if(!form.id)throw Error('请先选择现有营业日历或诊疗位');if(!form.impact_acknowledged||!form.unavailable_reason?.trim())throw Error('请填写真实不可用原因并确认接续责任');if(action.value==='calendar'&&form.is_open)throw Error('临时停业应关闭该营业时段');if(action.value==='operatory'&&form.resource_state==='active')throw Error('故障停用应选择维护中或停用')}
 const critical=['arrive','sign','confirm','stop','correct','approve','revoke','revoke-authority','cancel','reschedule'].includes(action.value)
 if(critical||(page.value==='UC15'&&form.change_mode==='immediate')){const yes=await new Promise<boolean>(resolve=>uni.showModal({title:'核对并确认',content:action.value==='arrive'?'请在实际到达预约门店后确认报到。报到更新候诊信息，实际接诊由牙医确认。':action.value==='sign'?'确认本次实际治疗及患者同意依据；签署后自动接续规则内结算。':`确认办理“${activeForm.value?.label}”？请核对当前患者、门店与版本。`,success:r=>resolve(r.confirm)}));if(!yes)return}
 const raw=JSON.stringify(payload);if(raw!==lastPayload.value){pendingKey.value=uuid();lastPayload.value=raw}
 result.value=await request('/api/use-cases/'+page.value,payload,pendingKey.value);if(bookingMode.value){slots.value=[];selectedSlot.value=null}toast(result.value.handover_required?'账号已停用，原业务责任保留；请由门店主管移交'+result.value.pending_followup_count+'项待约事项。':result.value.requires_verification?'实际记录已保留，待核实依据，不自动开具有效结算。':result.value.billing_state==='pending'?result.value.billing_message:'办理已完成');editorOpen.value=false;pendingKey.value='';lastPayload.value='';await refresh();Object.keys(form).forEach(k=>delete form[k])
 }catch(e:any){error.value=e.message}finally{busy.value=false}}
async function queryRecords(more=false){busy.value=true;error.value='';try{const existing=resources.value[activeDataset.value]||[];const before=more&&existing.length?'&before='+existing[existing.length-1].id:'';const data=await request('/api/records?resource='+activeDataset.value+'&q='+encodeURIComponent(query.value)+before);ws.value.resources[activeDataset.value]=more?[...existing,...data.items]:data.items}catch(e:any){error.value=e.message}finally{busy.value=false}}
function rowStatus(r:any){return format(r.resolution||r.progress_outcome||r.publication_state||r.approval_state||r.review_state||r.confirmation_state||r.resource_state||r.verification_result||r.validity||'')}
onMounted(async()=>{
 const data=await requireWorkspace(initialCode)
 if(!data)return
 ws.value=data
 choose(initialCode)
 if(initialDataset&&showingLists.value.includes(initialDataset))activeDataset.value=initialDataset
 const selected=initialId?list.value.find((row:Row)=>row.id===initialId):null
 if(selected)await inspectRecord(selected,!initialAction)
 if(initialAction&&availableActions.value.some(spec=>spec.key===initialAction)) {
  if(initialId&&!selected){error.value='记录已变更或超出当前范围，请刷新后重新选择';return}
  await openEditor(initialAction,selected||undefined)
 }
 if(personalProfile.value&&profilePatient.value.id&&!detail.value)await inspectRecord(profilePatient.value)
})

onShow(async()=>{if(!ws.value||work.authRequired)return;try{await refresh()}catch(e:any){error.value=e.message}})

const editorOpen=ref(false),actionsOpen=ref(false),statusFilter=ref(''),scheduleDay=ref(localDay()),viewMode=ref('list')
const copy=computed(()=>pageCopy[page.value]||{title:currentMenu.value?.name||'诊所业务',intro:'',rule:''})
const visibleRows=computed(()=>list.value.filter((r:Row)=>(!query.value||JSON.stringify(cells(activeDataset.value,r)).toLowerCase().includes(query.value.toLowerCase()))&&(!statusFilter.value||rowStatus(r)===statusFilter.value)))
const statuses=computed<string[]>(()=>[...new Set<string>(list.value.map((r:Row)=>rowStatus(r) as string).filter(Boolean))])
const detailFields=computed(()=>detail.value?Object.entries(detail.value.patient||detail.value).filter(([key,value])=>key in fieldNames&&value!==null&&typeof value!=='object').map(([key,value])=>({key,label:fieldNames[key],value:typeof value==='boolean'?(value?'是':'否'):format(String(value))})):[])
const historyExpanded=reactive<Record<string,boolean>>({profile:false,allergy:false})
const patientHistories=[{kind:'profile',key:'profile_history',title:'基本资料修订',fields:['full_name','birth_date','sex_code','billing_address','phone','email','change_reason']},{kind:'allergy',key:'allergy_history',title:'过敏申报与核实修订',fields:['substance_name','reaction_description','reporter_name','report_source','verification_result','correction_reason']}]
async function morePatientHistory(kind:string,key:string){if(!detail.value?.patient||!detail.value[key]?.next)return;busy.value=true;error.value='';try{const result=await request('/api/patients/'+detail.value.patient.id+'?history_kind='+kind+'&history_before='+detail.value[key].next);detail.value[key]={items:[...detail.value[key].items,...result.items],next:result.next}}catch(e:any){error.value=e.message}finally{busy.value=false}}
const formSections=computed(()=>{const fs=activeForm.value?.fields||[];if(page.value==='UC05')return [{title:'就诊与签署依据',fields:fs.filter(f=>f.key==='encounter_id'||f.key==='correction_reason'||f.key==='zero_charge_basis'||f.key==='exception_reason')},{title:'本次检查与诊疗记录',fields:fs.filter(f=>noteKeys.includes(f.key))},{title:'患者同意',fields:fs.filter(f=>['consent_scope','evidence_reference','signer_contact_id','authority_id'].includes(f.key))}];return [{title:activeForm.value?.label||'办理资料',fields:fs}]})
const noteKeys=['chief_complaint','present_illness','medical_history','examination_summary','tests_summary','diagnosis_summary','management_summary','aftercare','allergy_review']
const scheduleRows=computed(()=>(resources.value.duties||[]).filter((r:Row)=>localDay(r.starts_at)===scheduleDay.value))
const sourceStates=computed(()=>[{title:'营业与出诊',value:(resources.value.duties||[]).filter((r:Row)=>r.publication_state==='published').length+' 份发布',hint:'与当前门店授权范围一致'},{title:'诊疗资源',value:(resources.value.operatories||[]).filter((r:Row)=>r.resource_state==='active').length+' 个可用',hint:'完整时段联合核验'},{title:'例外接续',value:(resources.value.followups||[]).filter((r:Row)=>!r.closed_at).length+' 项待办',hint:'保留原安排及承接责任'}])
function pickDataset(key:string){activeDataset.value=key;recordFocus.value=null;detail.value=null;query.value='';statusFilter.value=''}
async function openEditor(key?:string,row?:Row) {
 const selected=key||availableActions.value[0]?.key
 if(!selected)return
 if(personalProfile.value&&selected===action.value&&Object.keys(form).length) {
  editorOpen.value=true
  return
 }
 changeAction(selected)
 if(row) {
  Object.assign(form,operationFields(page.value,selected,activeDataset.value,row,(activeForm.value?.fields||[]).map(field=>field.key)))
  editorSubject.value=optionLabel(row.patient||row)
  if(page.value==='UC01'&&selected==='save')fillEmergency(form.id)
  if(page.value==='UC05')await inspect(row)
  if(page.value==='UC13'&&activeDataset.value==='phases'&&selected!=='phase') {
   await inspect(row)
  }
 }
 editorOpen.value=true
 actionsOpen.value=false
}
function closeEditor(){editorOpen.value=false;error.value=''}

async function inspectRecord(row:Row,showDetail=true){
 recordFocus.value=row
 historyExpanded.profile=false
 historyExpanded.allergy=false
 await inspect(row)
 if(activeDataset.value==='patients'&&page.value==='UC01'){
  try{detail.value=await request('/api/patients/'+row.id)}
  catch(e:any){error.value=e.message}
 }
 if(showDetail&&!personal.value){
  await nextTick()
  uni.pageScrollTo({selector:'#business-record-detail',duration:0})
 }
}
function stepDate(offset:number){scheduleDay.value=localDay(new Date(scheduleDay.value+'T12:00:00+08:00').getTime()+offset*86400000 as any)}
async function findRecords(){if(['patients','appointments','invoices'].includes(activeDataset.value))await queryRecords();}
function submitLabel(){return page.value==='UC12'&&action.value==='analyze'?'核对季度来源并计算':activeForm.value?.label||'确认办理'}
</script>
<template>
 <WorkspaceShell :title="copy.title" :active="page" :hide-footer="editorOpen" back>
  <view class="page-heading"><view><text class="page-title">{{personalProfile?'我的资料':copy.title}}</text><text class="page-description">{{personalProfile?'个人信息、联系人与过敏记录，按项查看和修改。':copy.intro}}</text></view><view v-if="!personalProfile" class="heading-actions"><button v-if="!personal" @click="refresh().catch(e=>error=e.message)">刷新</button><button v-if="availableActions.length>1" @click="actionsOpen=!actionsOpen"><AppIcon name="more-filled" :size="18"/><text>更多操作</text></button><button v-if="availableActions.length&&!['UC14','UC17'].includes(page)" class="primary" @click="openEditor(availableActions[0]?.key)"><AppIcon name="plusempty" color="#ffffff" :size="18"/><text>{{page==='UC01'&&ws?.scope.role_code==='reception'?'新建患者档案':availableActions[0]?.label}}</text></button><button v-else-if="page==='UC17'" @click="submit">刷新记录</button></view></view>
  <view v-if="notice" class="notice" role="status"><AppIcon name="checkbox" :size="19"/><text>{{notice}}</text></view><view v-if="error&&!editorOpen" class="error">{{error}}</view>
  <view v-if="actionsOpen" class="action-menu surface"><button v-for="a in availableActions" :key="a.key" @click="openEditor(a.key)"><AppIcon :name="a.key.includes('revoke')||a.key==='stop'?'info':'compose'" :size="20"/><text>{{a.label}}</text><AppIcon name="right" :size="14"/></button></view>
  <view v-if="personalProfile" class="personal-profile">
   <view class="profile-section surface"><view class="profile-section-heading"><view><text class="section-title">基本资料</text><text class="caption">{{profilePatient.account_no}} · 跨店沿用同一档案</text></view><button class="text-button profile-edit" @click="openEditor('save')">修改资料 <AppIcon name="right" :size="14"/></button></view><view class="profile-info"><view v-for="item in profileInfo" :key="item.label"><text class="caption">{{item.label}}</text><text>{{item.value||'尚未填写'}}</text></view></view></view>
   <view class="profile-section surface"><view class="profile-section-heading"><view><text class="section-title">联系人</text><text class="caption">紧急联系与监护、代办用途分别登记</text></view><button class="text-button profile-contact-add" @click="openEditor('contact')">新增联系人 <AppIcon name="right" :size="14"/></button></view><view class="profile-contact-list"><view v-for="contact in profileContacts" :key="contact.id" class="profile-contact"><view><text class="item-name">{{contact.full_name}} · {{contact.relationship}}</text><text class="caption">{{contact.phone}}</text></view><text class="badge">{{format(contact.contact_purpose)}}</text></view><text v-if="!profileContacts.some(c=>c.contact_purpose==='emergency')" class="caption">尚未补充紧急联系人，请在修改基本资料时填写姓名及电话。</text></view></view>
   <view class="profile-section surface"><view class="profile-section-heading"><view><text class="section-title">过敏情况</text><text class="caption">{{format(profilePatient.allergy_declaration)}} · 申报与牙医核实分别留存</text></view><button class="text-button profile-allergy-add" @click="openEditor('allergy')">申报过敏 <AppIcon name="right" :size="14"/></button></view><view class="profile-contact-list"><view v-for="allergy in detail?.allergies||[]" :key="allergy.id" class="profile-contact"><view><text class="item-name">{{allergy.substance_name}}</text><text class="caption">{{allergy.reaction_description||'反应待补充'}} · {{allergy.report_source}}</text></view><text class="badge">{{format(allergy.verification_result)}}</text></view><text v-if="!detail?.allergies?.length" class="caption">暂无逐项过敏记录；这不表示已经确认无过敏。</text></view></view>
  </view>
  <view v-if="['UC09','UC15'].includes(page)" class="context-metrics"><view v-for="stat in sourceStates" :key="stat.title"><text class="caption">{{stat.title}}</text><text class="context-value">{{stat.value}}</text><text class="caption">{{stat.hint}}</text></view></view>
  <view v-if="page==='UC04'" class="care-stages"><view><AppIcon name="calendar"/><text>预约安排</text></view><AppIcon name="right" :size="14"/><view><AppIcon name="location"/><text>实际到店</text></view><AppIcon name="right" :size="14"/><view><AppIcon name="staff"/><text>牙医确认接诊</text></view><AppIcon name="right" :size="14"/><view><AppIcon name="compose"/><text>实际治疗</text></view></view>
  <view v-if="!personal&&showingLists.length&&availableActions.length" class="workflow-hint">
   <AppIcon name="info" :size="15"/><text>从表格打开记录后，可以按当前状态办理。新增或需要手动选记录时，使用页面顶部的操作。</text>
  </view>
  <view v-if="showingLists.length&&!personalProfile" class="view-tabs"><button v-for="key in showingLists" :key="key" :class="{selected:activeDataset===key}" @click="pickDataset(key)">{{datasetNames[key]}} <text>{{resources[key]?.length||0}}</text></button></view>
  <view v-if="showingLists.length&&!personalProfile" class="records-surface surface"><view class="records-toolbar"><view class="search-box"><AppIcon name="search" :size="19" color="#758296"/><input v-model="query" placeholder="搜索姓名、编号或业务记录" aria-label="搜索业务记录" @confirm="findRecords"/><button class="text-button" @click="findRecords">查询</button></view><view class="record-tools"><picker v-if="statuses.length>1" :range="['全部状态',...statuses]" @change="statusFilter=Number($event.detail.value)?statuses[Number($event.detail.value)-1]:''"><view class="filter-button"><AppIcon name="settings" :size="17"/><text>{{statusFilter||'全部状态'}}</text></view></picker><view v-if="page==='UC09'" class="display-switch"><button :class="{selected:viewMode==='list'}" @click="viewMode='list'">列表</button><button :class="{selected:viewMode==='day'}" @click="viewMode='day'">日程</button></view><text class="caption">{{visibleRows.length}} 条已读取记录</text></view></view>
   <template v-if="page==='UC09'&&viewMode==='day'"><view class="day-toolbar"><button class="icon-button" aria-label="前一天" @click="stepDate(-1)"><AppIcon name="left"/></button><picker mode="date" :value="scheduleDay" @change="scheduleDay=$event.detail.value"><button>{{scheduleDay}}</button></picker><button class="icon-button" aria-label="后一天" @click="stepDate(1)"><AppIcon name="right"/></button><button class="text-button" @click="scheduleDay=localDay()">今天</button></view><view class="duty-agenda"><view v-for="d in scheduleRows" :key="d.id" class="duty-session"><text class="session-time">{{clock(d.starts_at)}}<text>{{clock(d.ends_at)}}</text></text><view><text class="item-name">{{d.label}}</text><text class="caption">完整出诊 · {{format(d.publication_state)}}</text></view><button class="quiet small" @click="inspectRecord(d)">查看安排</button></view><view v-if="!scheduleRows.length" class="inline-empty">该日暂无已读取出诊，请选择其他日期。</view></view></template>
   <template v-else><view class="record-table-head"><text v-for="name in columnTitles[activeDataset]||[]" :key="name">{{name}}</text><text></text></view><view v-for="row in visibleRows" :key="row.id" role="button" tabindex="0" @keydown.enter="inspectRecord(row)" class="record-table-row" :class="{selected:detail?.id===row.id||detail?.patient?.id===row.id}" @click="inspectRecord(row)"><view v-for="(cell,i) in cells(activeDataset,row)" :key="i" :class="{'record-primary':i===0,'record-status':i===3}"><text class="mobile-cell-label">{{columnTitles[activeDataset]?.[i]}}</text><text :class="{badge:i===3}">{{cell}}</text></view><AppIcon name="right" :size="15" color="#758296"/></view><view v-if="!visibleRows.length" class="empty-state"><view class="empty-icon"><AppIcon name="folder-add" :size="32"/></view><text class="empty-title">{{query||statusFilter?'没有匹配的记录':'暂无'+(datasetNames[activeDataset]||'业务记录')}}</text><text>{{query||statusFilter?'可以调整关键词或状态条件。':'相关业务办理后会在这里呈现，不用重复建立记录。'}}</text></view></template>
   <view v-if="isRemoteList&&(resources[activeDataset]?.length||0)>=200" class="load-more"><button class="text-button" @click="queryRecords(true)">读取更早记录</button></view>
  </view>
  <view class="rule-note"><AppIcon name="info" :size="18"/><text>{{copy.rule}}</text></view>
  <view v-if="detail" id="business-record-detail" class="detail-surface surface"><view class="detail-header"><view><text class="section-title">{{personalProfile?'资料修订记录':datasetNames[activeDataset]+'详情'}}</text><text class="caption">{{labelRow(detail.patient||detail)}}</text></view><view class="heading-actions"><button v-if="page==='UC07'&&activeDataset==='clinics'&&canUse('UC09')" class="quiet small branch-schedule-link" @click="goCase('UC09',{clinic:detail.id})">查看该店排班</button><button v-for="item in rowActions" :key="item.action" class="quiet small" @click="openEditor(item.action,recordFocus||undefined)">{{item.label}}</button><button v-if="!personalProfile" class="icon-button" aria-label="关闭详情" @click="detail=null"><AppIcon name="closeempty"/></button></view></view>
   <view v-if="detailFields.length&&!personalProfile" class="detail-fields"><view v-for="field in detailFields" :key="field.key"><text class="caption">{{field.label}}</text><text>{{field.value}}</text></view></view>
   <view v-if="detail.current_revision" class="detail-content"><button class="text-button" @click="openInvoiceCopy">打开结算单副本 <AppIcon name="right" :size="15"/></button><view v-for="line in detail.lines" :key="line.id" class="invoice-line"><view><text>{{line.treatment_name_snapshot}}</text><text class="caption">{{Number(line.quantity_snapshot)}} {{line.unit_name_snapshot}} × ¥{{money(line.unit_price_snapshot)}}</text></view><text>¥{{money(line.subtotal)}}</text></view><view class="invoice-total"><text>有效版本 {{detail.current_revision.revision_no}} 合计</text><text>¥{{money(detail.current_revision.total_amount)}}</text></view></view>
   <view v-if="detail.plan_no&&detail.phases" class="detail-content"><view class="row between"><text class="section-title">方案第{{detail.revision?.revision_no}}版 · {{format(detail.revision?.confirmation_state)}}</text><button v-if="detail.revision?.confirmation_state==='draft'" class="text-button" @click="openEditor('confirm',detail)">核对并确认本版草案</button></view><view v-for="p in detail.phases" :key="p.phase_id" class="note-version"><text class="item-name">第{{p.phase_no}}阶段 · {{p.phase_title}}</text><text class="caption">{{p.clinical_condition}}</text><text class="caption">{{(resources.clinics||[]).find((c:Row)=>c.id===p.responsible_clinic_id)?.clinic_name}} · {{format(p.progress_outcome)}}</text><view v-for="item in p.items" :key="item.id" class="invoice-line"><text>{{(resources.standards||[]).find((t:Row)=>t.id===item.standard_id)?.treatment_name||'原方案项目'}} · {{item.site_description||'按临床核实部位'}}</text><text>{{Number(item.planned_quantity)}}</text></view></view><text class="caption">先决关系：{{detail.dependencies.length?detail.dependencies.map((d:Row)=>'阶段'+d.predecessor+' → 阶段'+d.successor).join('；'):'没有阶段依赖'}}</text></view>
   <view v-if="detail.allergies&&!personalProfile" class="detail-content"><text class="section-title">逐项过敏及核实</text><view v-for="a in detail.allergies" :key="a.id" class="allergy-line"><AppIcon name="info" :size="19"/><view><text class="item-name">{{a.substance_name}} · {{format(a.verification_result)}}</text><text class="caption">{{a.reaction_description}} · {{a.report_source}}</text></view></view><text v-if="!detail.allergies.length" class="caption">尚无逐项记录，不能据此认定无过敏。</text></view>
   <template v-if="detail.patient"><view v-for="history in patientHistories" :key="history.kind" class="detail-content"><button class="text-button" @click="historyExpanded[history.kind]=!historyExpanded[history.kind]">{{historyExpanded[history.kind]?'收起':'查看'}}{{history.title}} · 已读取 {{detail[history.key]?.items.length||0}} 条 <AppIcon :name="historyExpanded[history.kind]?'up':'down'" :size="14"/></button><template v-if="historyExpanded[history.kind]"><view v-for="revision in detail[history.key]?.items||[]" :key="revision.id" class="note-version"><view class="row between"><text>第 {{revision.revision_no}} 版 <text v-if="revision.substance_name"> · {{revision.substance_name}}</text></text><text class="caption">{{dateTime(revision.recorded_at)}}</text></view><text class="caption">记录人：{{revision.recorded_name}} · {{revision.replaces_id?'沿用原修订链':'首次登记'}}</text><view v-for="key in history.fields.filter(k=>revision[k]!=null&&revision[k]!=='')" :key="key" class="clinical-note"><text class="caption">{{fieldNames[key]||key}}</text><text>{{format(String(revision[key]))}}</text></view></view><button v-if="detail[history.key]?.next" :disabled="busy" @click="morePatientHistory(history.kind,history.key)">继续读取{{history.title}}</button><text v-if="!detail[history.key]?.items.length" class="caption">尚无修订记录；不能据此推断资料已核实。</text></template></view></template>
   <view v-if="detail.notes" class="detail-content"><text class="section-title">临床记录版本</text><view v-for="n in detail.notes" :key="n.id" class="note-version"><view class="row between"><text>第 {{n.revision_no}} 版</text><text class="badge">{{format(n.signature_state)}}</text></view><view v-for="key in noteKeys" :key="key" class="clinical-note"><text>{{({chief_complaint:'主诉',present_illness:'现病史',medical_history:'既往史',examination_summary:'检查所见',tests_summary:'辅助检查',diagnosis_summary:'诊断摘要',management_summary:'实际处置',aftercare:'复诊与注意事项',allergy_review:'过敏核实'} as any)[key]}}</text><text>{{n[key]||'未填写'}}</text></view></view></view>
  </view>
  <view v-if="result" class="result-surface surface"><view class="detail-header"><text class="section-title">{{page==='UC12'?'季度来源与计算结果':page==='UC17'?'操作记录':'本次办理结果'}}</text><text v-if="result.id" class="caption">记录 {{result.id}}{{result.replayed?' · 已返回原结果':''}}</text></view><view class="detail-content"><text v-if="result.requires_verification" class="badge">实际事实已保留，待核实后再签署开单</text><text v-else-if="result.billing_state" class="badge">{{result.billing_state==='current'?'诊疗已签署，结算已生成':'诊疗已签署，结算待处理'}}</text><template v-if="result.rows"><view class="finance-totals"><view><text class="caption">集团净利润合计</text><text>¥{{money(result.group_net_profit)}}</text></view><view><text class="caption">正向集团基金 · 10%</text><text>¥{{money(result.incentive_fund)}}</text></view></view><view v-if="result.issues?.length" class="quarter-issues"><text class="item-name">正式确认前需解决</text><text v-for="issue in result.issues" :key="issue">{{issue}}</text></view><view v-for="r in result.rows" :key="r.dentist_id+'-'+r.clinic_id" class="performance-row"><view><text class="item-name">{{r.dentist_name||'牙医'+r.dentist_id}} · {{r.clinic_name||'门店'+r.clinic_id}}</text><text class="caption">收入 ¥{{money(r.revenue)}} · 用品 ¥{{money(r.supplies_cost)}} · 运营 ¥{{money(r.operating_expense)}}</text></view><text>¥{{money(r.net_profit)}}</text></view></template><view v-for="r in result.items" :key="r.id" class="audit-row"><view class="audit-marker"><AppIcon name="checkbox" :size="18"/></view><view><text class="item-name">{{r.display_name}} · {{r.operation_name}}</text><text class="caption">{{dateTime(r.occurred_at)}} · {{r.business_reference}}</text></view><text class="badge">{{r.result_code||'已记录'}}</text></view><view v-if="page==='UC17'&&!result.items?.length" class="inline-empty">当前授权范围内暂无操作记录。</view></view></view>
  <view v-if="editorOpen" class="drawer-backdrop"><view class="business-editor" :style="nativeInsetStyle" @click.stop><view class="editor-header"><view><text class="section-title">{{activeForm?.label}}</text><text class="caption">{{copy.title}} · {{ws?.scope.role_name}}</text></view><button class="icon-button" aria-label="关闭办理面板" @click="closeEditor"><AppIcon name="closeempty"/></button></view><scroll-view scroll-y class="editor-scroll"><view class="editor-content"><view v-if="editorSubject" class="workflow-subject"><text>当前办理记录</text><text>{{editorSubject}}</text></view><view v-if="error" class="error">{{error}}</view><view v-if="page==='UC01'" class="info-strip">{{action==='authority'?'线下核实监护或代办资格不要求注册账号；线上办理需另外核实独立账号并授予对应患者范围。紧急联系人不自动具有同意权限。':action==='save'?'紧急联系人仅用于联系。已有过敏项不能用“否认”覆盖；请在逐项过敏中申报或由牙医核实。':'过敏申报保留实际来源与修订；本人或代办人不能自行确认临床结论。'}}</view><view v-for="group in formSections.filter(g=>g.fields.length)" :key="group.title" class="form-section"><text class="form-section-title">{{group.title}}</text><view class="form-grid"><view v-for="field in group.fields" :key="field.key" :id="'form-field-'+field.key" class="form-field-cell" :class="{'full-width':field.type==='textarea'||field.type?.startsWith('multi:')||field.type==='record'}"><AdcField :field="field" v-model="form[field.key]" :resources="formResources"/></view></view></view>
 <view v-if="page==='UC06'&&billingReview" class="repeater"><text class="section-title">{{billingReview.patient_name}} · 费用来源核对</text><text class="caption">{{billingReview.encounter_no}} · 临床版本{{billingReview.latest_note?.revision_no}} · {{format(billingReview.latest_note?.signature_state)}}</text><view v-for="item in billingReview.items" :key="item.treatment_id" class="invoice-line"><view><text>{{item.treatment_name}} · {{item.site_description||'未指定部位'}}</text><text class="caption">{{item.actual_quantity}} {{item.unit_name}} × ¥{{money(item.charged_unit_price)}} · 标准 ¥{{money(item.standard_price)}}</text><text class="caption">{{dateTime(item.performed_at)}} · {{format(item.implementation_result)}}</text><text v-if="item.charged_unit_price!==item.standard_price" class="caption">{{item.price_approved_by?'已记录独立批准依据':'非标准价格待批准'}}</text></view></view><view v-for="version in billingReview.invoice_versions" :key="version.id" class="note-version"><view class="row between"><text>结算第{{version.revision_no}}版 · {{format(version.validity)}}</text><text>¥{{money(version.total_amount)}}</text></view><text v-if="version.zero_charge_basis" class="caption">牙医零费用依据：{{version.zero_charge_basis}}</text><view v-for="line in version.lines" :key="line.id" class="invoice-line"><text>{{line.treatment_name_snapshot}} · {{line.quantity_snapshot}}{{line.unit_name_snapshot}}</text><text>¥{{money(line.subtotal)}}</text></view></view><text class="caption">核对实际数量、单位价格及保留的结算版本；此处不显示诊疗正文。费用更正须与牙医当前签署的实际明细一致。</text></view>
 <view v-if="page==='UC15'&&resourceImpact" class="repeater"><text class="section-title">现有安排影响</text><text class="caption">{{resourceImpact.appointments.length}}条完整时段内的安排；其中{{resourceImpact.ongoing_encounters_preserved}}次已接诊事实保留。</text><view v-for="a in resourceImpact.appointments" :key="a.id" class="rule-note">{{a.appointment_no}} · {{dayLabel(a.starts_at)}} {{clock(a.starts_at)}}—{{clock(a.ends_at)}} · {{format(a.resolution)}}</view><text class="caption">计划调整先处理现有承诺；真实故障立即阻止新约，原约保留为机构无法履行，进入门店接续队列。已经接诊的事实保持原样。</text></view>
 <view v-if="page==='UC05'"><view class="divider"></view><text class="section-title">实际实施明细</text><view v-for="(line,i) in clinicalLines" :key="i" class="repeater"><view class="row between"><text>实际治疗 {{i+1}}</text><button class="quiet danger small" @click="clinicalLines.splice(i,1)">移除</button></view><AdcField v-for="field in clinicalField" :key="field.key" :field="field" v-model="line[field.key]" :resources="formResources"/></view><button class="quiet" @click="addClinical">＋ 增加实际治疗</button><view class="divider"></view><text class="label">本次承接阶段的实施结果（如有）</text><view v-for="(r,i) in phaseResults" :key="i" class="repeater"><AdcField :field="{key:'phase_id',label:'承接阶段',type:'select:phases'}" v-model="r.phase_id" :resources="formResources"/><AdcField :field="{key:'outcome',label:'实施后结果',type:'enum:completed=已完成,ready=需继续且可约,waiting=待临床复评,paused=暂停,terminated=终止'}" v-model="r.outcome" :resources="formResources"/><AdcField :field="{key:'reason',label:'暂停或终止依据',type:'textarea'}" v-model="r.reason" :resources="formResources"/></view><button class="quiet" @click="phaseResults.push({phase_id:'',outcome:'completed'})">＋ 阶段实施结果</button></view>
 <view v-if="page==='UC11'&&action==='source'"><view class="divider"></view><text class="section-title">费用分摊</text><view v-for="(allocation,i) in allocations" :key="i" class="repeater"><AdcField v-for="field in allocationFields" :key="field.key" :field="field" v-model="allocation[field.key]" :resources="formResources"/><button class="quiet danger" @click="allocations.splice(i,1)">移除此项</button></view><button class="quiet" @click="addAllocation">＋ 增加分摊</button><text class="small muted" style="display:block">分摊合计：¥ {{allocations.reduce((s:number,a:any)=>s+Number(a.allocated_amount||0),0).toFixed(2)}}</text></view>
 <view v-if="page==='UC13'&&action!=='phase'"><view class="divider"></view><text class="section-title">阶段方案</text><view v-for="(phase,i) in phases" :key="i" class="repeater"><AdcField v-for="field in phaseFields" :key="field.key" :field="field" v-model="phase[field.key]" :resources="formResources"/><view v-for="(item,j) in phase.items" :key="j" class="repeater"><AdcField :field="{key:'standard_id',label:'计划项目',type:'select:standards',required:true}" v-model="item.standard_id" :resources="formResources"/><AdcField :field="{key:'planned_quantity',label:'预计数量',type:'number',required:true}" v-model="item.planned_quantity" :resources="formResources"/><AdcField :field="{key:'site_description',label:'计划部位',type:'text'}" v-model="item.site_description" :resources="formResources"/></view><button class="quiet" @click="phase.items.push({standard_id:'',planned_quantity:1})">＋ 计划项目</button><button class="quiet danger" @click="phases.splice(i,1)">移除本阶段</button></view><button class="quiet" @click="addPhase">＋ 增加阶段</button><view v-for="(dep,i) in dependencies" :key="i" class="grid repeater"><AdcField :field="{key:'predecessor',label:'先决阶段序号',type:'number'}" v-model="dep.predecessor" :resources="formResources"/><AdcField :field="{key:'successor',label:'后继阶段序号',type:'number'}" v-model="dep.successor" :resources="formResources"/></view><button class="quiet" @click="dependencies.push({predecessor:1,successor:2})">＋ 增加先决关系</button></view>

    <text v-if="pendingKey" class="caption">如网络中断，请保留当前表单重试，以获取原有办理结果。</text></view></scroll-view><view class="editor-footer"><button :disabled="busy" @click="closeEditor">收起，保留填写</button><button class="primary submit-button" :disabled="busy" @click="submit">{{busy?'办理中…':submitLabel()}}</button></view></view></view>
 </WorkspaceShell>
</template>
